import { readFileSync, writeFileSync } from "node:fs"
type Entry = { readonly value: string; readonly at: number }
export function load(path: string): string {
  const entry: Entry = JSON.parse(readFileSync(path, "utf8"))
  return entry.value
}
export function save(path: string, value: string): void {
  const entry: Entry = { value, at: 0 }
  writeFileSync(path, JSON.stringify(entry))
}
export const encoding = "utf8"

import { readFileSync } from "node:fs"
type Manifest = { readonly name: string; readonly main: Main }
type Main = { readonly file: string }
export interface Plugin { readonly name: string }
export function loadPlugin(path: string): Plugin {
  const manifest: Manifest = JSON.parse(readFileSync(path, "utf8"))
  return { name: manifest.name + manifest.main.file }
}
export function describe(plugin: Plugin): string { return plugin.name }
